const pipeline = `
  <div class="pipeline-groups">
    <section class="pipeline-group"><span>01 / Integrity</span><h3>Preserve</h3><ol><li><strong>Acquire</strong><small>Fetch a named official source.</small></li><li><strong>Hash and archive</strong><small>Keep an immutable copy and digest.</small></li></ol></section>
    <section class="pipeline-group"><span>02 / Consistency</span><h3>Normalize</h3><ol><li><strong>Validate schema</strong><small>Reject malformed records.</small></li><li><strong>Normalize units</strong><small>Standardize dates, amounts, and scale.</small></li><li><strong>Reconcile controls</strong><small>Compare with published totals.</small></li></ol></section>
    <section class="pipeline-group"><span>03 / Identity</span><h3>Link</h3><ol><li><strong>Match identity</strong><small>Connect records with explainable evidence.</small></li><li><strong>Classify confidence</strong><small>Keep uncertainty visible.</small></li></ol></section>
    <section class="pipeline-group"><span>04 / Decision</span><h3>Review</h3><ol><li><strong>Calculate anomalies</strong><small>Run deterministic rules.</small></li><li><strong>Quarantine</strong><small>Hold conflicts and weak evidence.</small></li><li><strong>Publish</strong><small>Release only passing records.</small></li></ol></section>
  </div>`;

export const methodologyBody = `
  <section class="page-intro"><div><p class="kicker">Methodology</p><h1>Every public link needs a source trail.</h1></div><div><p class="lede">Collection, normalization, matching, review, and publication are separated so that a plausible relationship cannot quietly become a public claim.</p>${methodDiagram}</div></section>
  <nav class="local-nav" aria-label="Methodology sections"><span>Jump to</span><a href="#pipeline">Pipeline</a><a href="#source-policy">Source policy</a><a href="#coverage-automation">Coverage automation</a><a href="#agency-ledger">Agency ledger</a><a href="#allotment-releases">Allotment releases</a><a href="#budget-cycle">Budget trail</a><a href="#procurement">Procurement</a><a href="#public-value">Public value</a><a href="#release-standard">Release standard</a><a href="#corrections">Corrections</a><a href="#editorial-independence">Independence</a></nav>

  <section class="narrative-section" id="pipeline" aria-labelledby="pipeline-heading">
    <div class="section-heading"><p class="section-number">01 / Pipeline</p><div><h2 id="pipeline-heading">Ten controls. Four evidence stages.</h2><p class="section-intro">A failure at any stage prevents publication. Quarantine is an intended outcome, not an exception.</p></div></div>${pipeline}
  </section>

  <section class="narrative-section" id="source-policy" aria-labelledby="source-heading">
    <div class="section-heading"><p class="section-number">02 / Source policy</p><div><h2 id="source-heading">Confidence follows evidence.</h2><p class="section-intro">Names alone are not enough to establish that two records refer to the same project. Machine-readable provenance stays in the JSON API. Reader actions open Busisi explanations, official document indexes, or source PDFs instead of raw JSON.</p></div></div>
    <div class="policy-grid">
      <article class="policy-item"><span>EXACT</span><h3>Direct identifier match</h3><p>Stable identifiers and compatible official fields point to the same record.</p></article>
      <article class="policy-item"><span>HIGH CONFIDENCE</span><h3>Multiple facts agree</h3><p>Location, agency, description, amount, and timing agree without material conflict.</p></article>
      <article class="policy-item"><span>CANDIDATE</span><h3>Human review required</h3><p>Some evidence aligns, but ambiguity or missing fields prevent a public link.</p></article>
    </div>
    <div class="standards-grid"><article class="standard-panel"><h3>Congressional district context</h3><p>District and representative names come from a hashed, dated 20th Congress roster snapshot linked to official House member profiles. Project context is assigned only through an exact listed DPWH office mapping. Shared offices show every served district, and unmatched offices remain unavailable.</p></article><article class="standard-panel"><h3>Boundary of the attribution</h3><p>This is not a coordinate or boundary-polygon determination. It does not show who requested, sponsored, controlled, inserted, or is responsible for a project or amount.</p></article></div>
    <div class="standards-grid"><article class="standard-panel"><h3>Original publisher</h3><p>The government agency or institution that published the underlying record remains identified separately from the service used to acquire it.</p></article><article class="standard-panel"><h3>Access route</h3><p>Selected public datasets and API records are accessed directly or through BetterGov.ph. BetterGov is credited as a civic-data access source, not as the original publisher.</p></article><article class="standard-panel"><h3>Processing and publication</h3><p>Busisi archives fingerprints, normalizes fields, reconciles controls, applies its published rules, and remains responsible for the resulting presentation.</p></article></div>
    <p class="evidence-limit">BetterGov does not operate, sponsor, or endorse Busisi and is not responsible for Busisi review signals, interpretations, or publication choices.</p>
  </section>

  <section class="narrative-section" id="coverage-automation" aria-labelledby="coverage-automation-heading">
    <div class="section-heading"><p class="section-number">03 / Coverage automation</p><div><h2 id="coverage-automation-heading">Discovery can be automatic. Trust cannot be assumed.</h2><p class="section-intro">The private queue uses a source image hint only to decide what to check next. It does not use that hint as evidence and never exposes private acquisition state.</p></div></div>
    <div class="standards-grid"><article class="standard-panel"><h3>Exact-only publication</h3><p>The project detail and image endpoint must report the same count. Every image must come from the registered DPWH media origin, pass bounded JPEG inspection, and match its archived SHA-256 identity. Count conflicts are archived and quarantined.</p></article><article class="standard-panel"><h3>Monotonic release gate</h3><p>A candidate release cannot reduce contract coverage, reduce verified-image coverage, or alter previously released immutable media. Failed candidates leave the last passing release public. Retry, blocked, and pending states remain coverage gaps.</p></article></div>
    <p><a href="/coverage/">View the latest gated coverage release</a></p>
  </section>

  <section class="narrative-section" id="agency-ledger" aria-labelledby="agency-ledger-heading">
    <div class="section-heading"><p class="section-number">04 / Agency ledger</p><div><h2 id="agency-ledger-heading">Compare only totals with the same appropriation scope.</h2><p class="section-intro">The FY2027 ledger joins 39 exact NEP appropriation-head identities to the third-reading House bill. Each House value is extracted from a declared PDF page and the complete set reconciles to the bill's printed control.</p></div></div>
    <div class="standards-grid"><article class="standard-panel"><h3>Source and arithmetic controls</h3><p>Original PDF and API bytes are archived by SHA-256. Money is stored as integer centavos. The NEP heads reconcile to ₱7.200186 trillion; the House-comparable heads reconcile to the printed ₱4.606066495 trillion new-appropriations control.</p></article><article class="standard-panel"><h3>Stage and hierarchy controls</h3><p>Automatic Appropriations are outside the House bill control and remain not applicable. The five Congress institutions are child rows, so they are never added again to the national total. Senate, bicameral, GAA, release, obligation, and payment stages remain unavailable until comparable evidence is acquired.</p></article></div>
  </section>

  <section class="narrative-section" id="allotment-releases" aria-labelledby="allotment-releases-heading">
    <div class="section-heading"><p class="section-number">05 / Releases</p><div><h2 id="allotment-releases-heading">Reconcile releases before comparing execution.</h2><p class="section-intro">The FY2026 ledger is a dated DBM status report, separate from the FY2027 proposal and legislation desks. It preserves the report's department, attached-agency, subunit, and Special Purpose Fund hierarchy.</p></div></div>
    <div class="standards-grid"><article class="standard-panel"><h3>Source and control tests</h3><p>The original XLSX is archived under SHA-256. Workbook values in thousand pesos are normalized to integer centavos. Current GAA and all-source program, release, and balance totals must reconcile exactly before any row is published.</p></article><article class="standard-panel"><h3>Interpretation boundary</h3><p>An allotment release is authority made available by DBM. It is not an obligation, Notice of Cash Allocation, disbursement, contractor payment, receipt, completion certificate, output, or outcome. These totals cannot be assigned to a project without a separate exact official link.</p></article></div>
  </section>

  <section class="narrative-section" id="budget-cycle" aria-labelledby="budget-cycle-heading">
    <div class="section-heading"><p class="section-number">06 / Budget trail</p><div><h2 id="budget-cycle-heading">Classify the document, not the website that hosts it.</h2><p class="section-intro">A fiscal-year portal can publish Executive, House, Senate, bicameral, enacted, and supporting records. Busisi assigns a stage only from explicit document evidence and keeps acquisition status separate from stage.</p></div></div>
    <div class="standards-grid"><article class="standard-panel"><h3>Three acquisition states</h3><p>Archived copy verified means retained bytes pass their recorded SHA-256 check. Catalogue record only means the official listing was observed but the file bytes were not acquired. Not yet acquired means no qualifying document is present, and never means zero.</p></article><article class="standard-panel"><h3>Blocked source boundary</h3><p>The Senate portal currently blocks ordinary server-side acquisition. A disclosed secondary renderer may discover catalogue identifiers and titles, but it cannot make its representation an official artifact. Mirror documents remain labeled as mirrors and must match their recorded fingerprints.</p></article></div>
  </section>

  <section class="narrative-section" id="procurement" aria-labelledby="procurement-heading">
    <div class="section-heading"><p class="section-number">07 / Procurement</p><div><h2 id="procurement-heading">A contract ID must survive every source boundary.</h2><p class="section-intro">Busisi links procurement evidence only through an exact contract ID or solicitation number. APP dates remain planned, PMR dates remain agency-reported, and PhilGEPS notices retain their own scope.</p></div></div>
    <div class="standards-grid"><article class="standard-panel"><h3>Amounts and events</h3><p>ABC, contract cost, and difference are stored as integer centavos. Event order is validated, and planned dates are never presented as actual dates. Contract outcome checks compare procurement fields with the DPWH delivery snapshot without silently choosing one source over another.</p></article><article class="standard-panel"><h3>Document acquisition</h3><p>Each lifecycle target is classified separately as archived official evidence, an indexed but unarchived source, a blocked acquisition, secondary evidence, or not located. A date reported in a PMR is not counted as acquisition of the signed contract, Notice to Proceed, completion certificate, inspection record, acceptance record or payment record.</p></article><article class="standard-panel"><h3>What procurement cannot prove</h3><p>A posting or PMR row does not establish release, payment, inspection quality, physical completion, public value, or COA clearance. A delivery-record contractor is not a verified awardee without an acquired award notice or signed contract. Missing evidence does not mean procurement did not occur.</p></article></div>
  </section>

  <section class="narrative-section" id="public-value" aria-labelledby="public-value-heading">
    <div class="section-heading"><p class="section-number">08 / Public value</p><div><h2 id="public-value-heading">No composite score and no inferred motive.</h2><p class="section-intro">The public-value desk keeps economy, fiscal space, composition, readiness, distribution, and delivery as separate questions. A favorable forecast cannot cancel weak project evidence.</p></div></div>
    <div class="standards-grid"><article class="standard-panel"><h3>Deterministic fiscal directions</h3><p>FY2026 and FY2027 cells come from DBM BESF Tables A.1 and A.2. Every row declares whether higher or lower is treated as favorable. Rows without an inherently favorable direction remain context only. Counts are descriptive and are never combined into a grade.</p></article><article class="standard-panel"><h3>Evidence boundary</h3><p>Forecasts are not observed outcomes. Appropriations are authority to spend, not releases, obligations, payments, completed outputs, or public benefit. Motive cannot be inferred from an amount, movement, sponsor name, or location.</p></article></div>
  </section>

  <section class="narrative-section" id="release-standard" aria-labelledby="release-heading">
    <div class="section-heading"><p class="section-number">09 / Publication standard</p><div><h2 id="release-heading">The register opens only after measured review.</h2></div></div>
    <div class="standards-grid"><article class="standard-panel"><h3>Required before release</h3><p>At least <strong>100 reviewed linkage cases</strong>, at least 95% measured precision, at least 95% reviewer agreement, and no unresolved critical reconciliation failure.</p></article><article class="standard-panel"><h3>How to read a signal</h3><p>A signal identifies a record pattern for examination. It is <strong>not evidence of wrongdoing</strong>, waste, or unlawful conduct.</p><p>Every published signal must show its rule, inputs, confidence, source references, and known limitations.</p></article></div>
  </section>

  <section class="narrative-section" id="corrections" aria-labelledby="corrections-heading">
    <div class="section-heading"><p class="section-number">10 / Corrections</p><div><h2 id="corrections-heading">Corrections keep their history.</h2><p class="section-intro">A correction preserves the prior version, records what changed, and identifies the evidence behind the decision. A record that loses support returns to quarantine.</p></div></div>
  </section>

  <section class="narrative-section" id="editorial-independence" aria-labelledby="editorial-independence-heading">
    <div class="section-heading"><p class="section-number">11 / Editorial independence</p><div><h2 id="editorial-independence-heading">Nonpartisan by policy.</h2><p class="section-intro">Busisi exists to help Filipino citizens examine public money. It has no affiliation with any politician, political party, candidate, or government faction and does not endorse or oppose them.</p></div></div>
    <div class="standards-grid"><article class="standard-panel"><h3>Same rules for every record</h3><p>Every agency, district, contractor, project, and public official is evaluated under the same published evidence rules. Names, offices, locations, and amounts do not change a threshold or turn a review signal into a finding.</p></article><article class="standard-panel"><h3>Data before interpretation</h3><p>Official records, derived comparisons, review signals, and verified findings remain separate. Busisi does not infer political motive from an amount or association, and it publishes coverage limits and correction history so readers can examine possible sources of bias.</p></article><article class="standard-panel"><h3>Ownership and contact</h3><p>Auva Labs is responsible for Busisi's software, data pipeline, methodology, presentation, and publication decisions. Data-source organizations do not control Busisi's classifications or conclusions. Questions, corrections, and source-backed challenges are welcome at <a href="mailto:dev@auvalabs.com">dev@auvalabs.com</a>.</p></article></div>
  </section>`;

